"use strict";(globalThis.webpackChunkgrc||=[]).push([[89564],{55906(e){e.exports=JSON.parse('{"citeKey":"lu2024aces","slug":"lu-2024-aces-6fdd","title":"ACES: Accelerating Sparse Matrix Multiplication with Adaptive Execution Flow and Concurrency-Aware Cache Optimizations","authors":["X. Lu","B. Long","X. Chen","Y. Han","X.-H. Sun"],"venue":"The 29th ACM International Conference on Architectural Support for Programming Languages and Operating Systems (ASPLOS-29)","type":"Conference","entryType":"inproceedings","date":"April, 2024","year":2024,"era":"iit","month":4,"doi":"10.1145/3620666.3651381","abstract":"Sparse matrix-matrix multiplication (SpMM) is a critical com- putational kernel in numerous scientific and machine learn- ing applications. SpMM involves massive irregular memory accesses and poses great challenges to conventional cache- based computer architectures. Recently dedicated SpMM accelerators have been proposed to enhance SpMM per- formance. However, current SpMM accelerators still face challenges in adapting to varied sparse patterns, fully ex- ploiting inherent parallelism, and optimizing cache perfor- mance. To address these issues, we introduce ACES, a novel SpMM accelerator in this study. First, ACES features an adaptive execution flow that dynamically adjusts to diverse sparse patterns. The adaptive execution flow balances par- allel computing efficiency and data reuse. Second, ACES incorporates locality-concurrency co-optimizations within the global cache. ACES utilizes a concurrency-aware cache management policy, which considers data locality and con- currency for optimal replacement decisions. Additionally, the integration of a non-blocking buffer with the global cache en- hances concurrency and reduces computational stalls. Third, the hardware architecture of ACES is designed to integrate all innovations. The architecture ensures efficient support across the adaptive execution flow, advanced cache opti- mizations, and fine-grained parallel processing. Our perfor- mance evaluation demonstrates that ACES significantly out- performs existing solutions, providing a 2.1\xd7 speedup and marking a substantial advancement in SpMM acceleration.","hasAbstract":true,"lede":"To address these issues, we introduce ACES, a novel SpMM accelerator in this study.","links":{"pdf":"https://grc.iit.edu/papers/2024/lu-2024-aces-6fdd.pdf","slides":"https://grc.iit.edu/papers/2024/lu-2024-aces-6fdd-slides.pdf","poster":"https://grc.iit.edu/papers/2024/lu-2024-aces-6fdd-poster.pdf"},"tags":["SpMM","Accelerator","Parallelism","Concurrency","Synchronization","Scalability","UniMCC"],"_projectIds":["unimcc","memory-access-obfuscation","smc2-planning","optmem"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["unimcc","memory-access-obfuscation","optmem","smc2-planning"],"memberAuthors":["lu-xiaoyang","sun-xian-he"],"funding":[{"agency":"NSF","award":"CNS-2310422","projectId":"unimcc"},{"agency":"NSF","award":"CNS-2152497","projectId":"memory-access-obfuscation"},{"agency":"NSF","award":"CCF-2029014","projectId":"smc2-planning"},{"agency":"NSF","award":"CCF-2008907","projectId":"optmem"}]}')}}]);